// Loop through incoming items from the LLM node
return $input.all().map(item => {
  // Adjust 'output' to match your LLM node's actual text field name (e.g., text, message, or response)
  let rawText = item.json.output || item.json.text || "";

  // 1. Clean up markdown code blocks if the LLM added them
  let cleanedText = rawText.replace(/```json/g, "").replace(/```/g, "").trim();

  let parsedEmail;
  try {
    // 2. Parse the JSON string into a JavaScript object
    parsedEmail = JSON.parse(cleanedText);
  } catch (error) {
    // Fallback in case the LLM output wasn't valid JSON
    parsedEmail = {
      to: "",
      cc: "",
      subject: "Error Parsing Email",
      body: rawText // Pass the raw text through so you don't lose data
    };
  }

  // 3. Return the structured data for the next node
  return {
    json: {
      to: parsedEmail.to,
      cc: parsedEmail.cc,
      subject: parsedEmail.subject,
      body: parsedEmail.body
    }
  };
});
